<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { NModal,NButton,NInput,NSelect,NCheckbox } from 'naive-ui'
import { message, type Row } from '../api'
import { t, renderText, type Text } from '../i18n'
export interface FormField {key:string;label:Text;placeholder?:Text;type?:'password'|'textarea'|'select'|'checkbox'|'number';options?:{label:Text;value:string}[];required?:boolean;initial?:unknown;hint?:Text}
const props = defineProps<{show:boolean;title:unknown;fields:FormField[];submit:(values:Row)=>Promise<unknown>;description?:unknown}>()
const emit = defineEmits<{'update:show':[value:boolean];saved:[]}>()
const values=ref<Row>({}),busy=ref(false),error=ref<unknown>(''),missingField=ref('')
const renderedFields = computed(() => props.fields.map(field => ({ ...field, label: renderText(field.label), placeholder: field.placeholder === undefined ? undefined : renderText(field.placeholder), hint: renderText(field.hint), options: field.options?.map(option => ({...option, label:renderText(option.label)})) })))
const validation = computed(() => missingField.value ? t('common.required', {field: renderText(props.fields.find(field => field.key === missingField.value)?.label)}) : message(error.value))
watch(() => props.show, show => {if(show){values.value=Object.fromEntries(props.fields.map(f=>[f.key,f.initial??(f.type==='checkbox'?false:'')]));error.value='';missingField.value=''}})
async function save(){error.value='';missingField.value='';for(const f of props.fields)if(f.required&&!values.value[f.key]){missingField.value=f.key;return}busy.value=true;try{await props.submit(values.value);emit('saved');emit('update:show',false)}catch(e){error.value=e}finally{busy.value=false}}
</script>
<template><n-modal :show="show" @update:show="emit('update:show',$event)" preset="card" :title="renderText(title)" class="dialog"><p v-if="description" class="muted">{{ renderText(description) }}</p><form @submit.prevent="save"><div v-for="f in renderedFields" :key="f.key" class="form-field"><label :for="`field-${f.key}`">{{ f.label }} <span v-if="f.required" class="required">*</span></label><n-checkbox v-if="f.type==='checkbox'" :checked="Boolean(values[f.key])" @update:checked="values[f.key]=$event">{{ t('common.enabled') }}</n-checkbox><n-select filterable v-else-if="f.type==='select'" :input-props="{id:`field-${f.key}`}" :value="String(values[f.key]??'')" :options="f.options" @update:value="values[f.key]=$event"/><n-input v-else :input-props="{id:`field-${f.key}`,autocomplete:f.type==='password'?'new-password':'off'}" :value="String(values[f.key]??'')" :type="f.type==='password'?'password':f.type==='textarea'?'textarea':'text'" :autosize="f.type==='textarea'?{minRows:4,maxRows:12}:undefined" :placeholder="f.placeholder" @update:value="values[f.key]=$event"/><small v-if="f.hint">{{ f.hint }}</small></div><p v-if="missingField||error" class="inline-error" role="alert">{{ validation }}</p><div class="actions"><n-button @click="emit('update:show',false)">{{ t('common.cancel') }}</n-button><n-button type="primary" attr-type="submit" :loading="busy">{{ t('common.saveExecute') }}</n-button></div></form></n-modal></template>
